import boto3
import json
import os

class BedrockEmbeddingsClient:
    def __init__(self, region_name=None, model_id="amazon.titan-embed-text-v2:0"):
        self.region_name = region_name or os.environ.get("AWS_REGION", "us-east-1")
        self.model_id = model_id
        self.client = boto3.client("bedrock-runtime", region_name=self.region_name)

    def invoke_model(self, text_input):
        body = json.dumps({"inputText": text_input})
        response = self.client.invoke_model(
            modelId=self.model_id,
            body=body,
            contentType="application/json",
            accept="application/json"
        )
        stream = response["body"]
        try:
            return json.loads(stream.read())
        finally:
            stream.close()

    def invoke_model_batch(self, text_inputs):
        # Bedrock's invoke_model doesn't directly support batch.
        # This is a conceptual helper for batching on the client side.
        embeddings = []
        for text in text_inputs:
            result = self.invoke_model(text)
            embeddings.append(result.get("embedding"))
        return {"embeddings": embeddings}

class EmbeddingsRequest:
    def __init__(self, texts):
        self.texts = texts

    def to_bedrock_batch_input(self):
        # For models like Titan Text Embeddings, each text is a separate call
        # This method prepares a list of individual inputs.
        return [{"inputText": text} for text in self.texts]


class EmbeddingsResponse:
    def __init__(self, bedrock_response_data):
        self.embeddings = [item["embedding"] for item in bedrock_response_data]


def normalize_embedding(embedding):
    # Basic normalization (e.g., to unit vector) if needed. Bedrock embeddings are often already normalized.
    # For simplicity, we return as is here.
    return embedding

import numpy as np
from embeddings_client import BedrockEmbeddingsClient

def cosine_similarity(embedding1, embedding2):
    return np.dot(embedding1, embedding2) / (np.linalg.norm(embedding1) * np.linalg.norm(embedding2))

def similarity_score(payload, config=None):
    config = config or {}
    client = BedrockEmbeddingsClient(
        region_name=config.get("region"),
        model_id="amazon.titan-embed-text-v2:0"
    )

    text1 = payload["text1"]
    text2 = payload["text2"]

    embedding1_response = client.invoke_model(text1)
    embedding1 = embedding1_response["embedding"]

    embedding2_response = client.invoke_model(text2)
    embedding2 = embedding2_response["embedding"]

    score = cosine_similarity(embedding1, embedding2)
    return {"similarity_score": score}

from embeddings_client import BedrockEmbeddingsClient

def embed_for_search(payload, config=None):
    config = config or {}
    client = BedrockEmbeddingsClient(
        region_name=config.get("region"),
        model_id="amazon.titan-embed-text-v2:0"
    )

    query_text = payload["query"]
    document_texts = payload["documents"]

    query_embedding_response = client.invoke_model(query_text)
    query_embedding = query_embedding_response["embedding"]

    document_embeddings = []
    for doc_text in document_texts:
        doc_embedding_response = client.invoke_model(doc_text)
        document_embeddings.append(doc_embedding_response["embedding"])

    return {
        "query_embedding": query_embedding,
        "document_embeddings": document_embeddings
    }

import os
from anthropic import Anthropic

def embedding_job_summary(payload, config=None):
    config = config or {}
    client = Anthropic(api_key=os.environ.get("ANTHROPIC_API_KEY"))

    job_results = payload["job_results"]
    summary_prompt = "Summarize the following embedding job results in a concise manner:\n\n"
    for result in job_results:
        summary_prompt += f"- Task: {result.get("task", "N/A")}, Status: {result.get("status", "N/A")}, Details: {result.get("details", "N/A")}\n"

    response = client.messages.create(
        model="claude-3-opus-20240229",
        max_tokens=200,
        messages=[
            {"role": "user", "content": summary_prompt}
        ]
    )
    return {"summary": response.content[0].text}

from google.cloud import translate_v3 as translate
import os

def multilingual_query_translate(payload, config=None):
    config = config or {}
    # Ensure GOOGLE_APPLICATION_CREDENTIALS is set for authentication
    # os.environ["GOOGLE_APPLICATION_CREDENTIALS"] = "/path/to/your/key.json"
    client = translate.TranslationServiceClient()

    project_id = os.environ.get("GOOGLE_CLOUD_PROJECT_ID") # Replace with your GCP project ID
    if not project_id:
        raise ValueError("GOOGLE_CLOUD_PROJECT_ID environment variable not set.")

    location = "global"
    parent = f"projects/{project_id}/locations/{location}"

    query_text = payload["query"]
    target_languages = payload["target_languages"]
    translated_queries = {}

    for lang_code in target_languages:
        response = client.translate_text(
            request={
                "parent": parent,
                "contents": [query_text],
                "target_language_code": lang_code,
            }
        )
        for translation in response.translations:
            translated_queries[lang_code] = translation.translated_text

    return {"original_query": query_text, "translated_queries": translated_queries}
